#!/usr/bin/env python3
"""Cycle-015 E7: VIEWS.md regeneration from the family files (tier text on the
nine moved techniques, new rows for T145-T165 + AS-59..AS-69 in exactly the
views their Feeds/consumer fields name, header re-pointed to the family files)
+ INDEX.md Cycle-015 update."""
import re, os
LIB = os.path.expanduser('~/workspace/goals/diy-building-and-real-learning/hidden_files/study/style-library')

# ---------- VIEWS ----------
vp = os.path.join(LIB, 'VIEWS.md')
v = open(vp).read()
v = v.replace(
 "_DERIVED FILE — regenerated by the style-library job from TECHNIQUES.md `Feeds:` fields + ASSETS.md consumer lines at every registration and tier move (style-library INSTRUCTION Amendment A5).",
 "_DERIVED FILE — regenerated by the style-library job from the seven family files' canonical-entry `Feeds:` fields (the register's post-split source, from Cycle-015; TECHNIQUES.md is now the governance surface) + ASSETS.md consumer lines at every registration and tier move (style-library INSTRUCTION Amendment A5).")
# replace the bold regenerated-note paragraph (starts '**Views regenerated:')
v = re.sub(r'\*\*Views regenerated:.*?\*\*', (
 "**Views regenerated: 2026-11-16, style-library Cycle-015 (register split executed — views now derive from the seven family files · packet #8 registered — 21 techniques T145–T165 + 11 assets AS-59…AS-69 added per their Feeds/consumer fields, 2 variants folded under AS-06/AS-07 · tier moves on recreation Waves 19/20 + practice Wave 15 scores — T133/T134/T135/T137/T139/T140/T105/T107 RECREATED · T132 IN PROGRESS: DESCRIBED 94 · IN PROGRESS 21 · RECREATED 50 · techniques 165 · assets 66). Tier text updated on the existing view lines of all nine moved techniques.**"), v, count=1, flags=re.S)

TIER_TXT = {
 'T105': '**RECREATED** (attempt 2: 91.6 PASS)', 'T107': '**RECREATED** (attempt 2: 87.8 PASS)',
 'T132': '**IN PROGRESS** (attempt 1: 83.2)', 'T133': '**RECREATED** (attempt 1: 88.0 PASS)',
 'T134': '**RECREATED** (attempt 1: 89.6 PASS)', 'T135': '**RECREATED** (attempt 1: 87.6 PASS)',
 'T137': '**RECREATED** (attempt 1: 91.0 PASS)', 'T139': '**RECREATED** (attempt 1: 88.4 PASS)',
 'T140': '**RECREATED** (attempt 1: 88.0 PASS)'}
lines = v.splitlines()
for i, ln in enumerate(lines):
    m = re.match(r'\| (T\d+) ', ln)
    if m and m.group(1) in TIER_TXT:
        cells = ln.split('|')
        cells[2] = ' ' + TIER_TXT[m.group(1)] + ' '
        lines[i] = '|'.join(cells)
v = '\n'.join(lines)

NEW_ROWS = {
 '## Openings': [
  '| T145 Scale-cascade cold open | DESCRIBED — **OWED #72** | abundance contracts into emptiness in one move | P8 @ 0:00–0:20 |',
  '| T146 Thesis-as-spoiler | DESCRIBED | the answer previewed before the questions | P8 @ 0:20–0:50 |',
  '| T147 Disclaimer with literalised visual gag | DESCRIBED | contract after the hook, staged as a pour | P8 @ 0:50–1:00 |',
  '| T148 Question-ladder sectioning | DESCRIBED | spoken questions as the chapter spine | P8 @ 1:00–8:29 |',
  '| AS-59 Question ladder as the section spine | asset | sections are questions, not topics | P8 lessons (§6 L1) |',
  '| AS-60 Speculation contract placement | asset | sign the contract after the hook, before the argument | P8 lessons (§6 L2) |'],
 '## Transitions': [
  '| T155 Ornate chapter cards | DESCRIBED | two cards only, at the irreversible turns | P8 @ 5:22, 8:30 |',
  '| T160 Expansion-front envelopment | DESCRIBED — **OWED #79** | a border arriving (also canonical in Diagrams) | P8 @ 7:26–7:36 |',
  '| AS-65 Chapter-card rationing | asset | card budget is a Plan decision | P8 lessons (§6 L9) |',
  '| AS-66 The envelopment diagram | asset | threat as pure geometry (also in Diagrams) | P8 lessons (§6 L10) |'],
 '## Diagrams': [
  '| T149 Isometric hard-steps path | DESCRIBED — **OWED #73** | steps as a returnable board-game staircase | P8 @ 1:20–1:50 |',
  '| T150 Platform menagerie | DESCRIBED | a statistic staged as animals on pedestals | P8 @ ~2:05–2:20 |',
  '| T151 Galaxy-of-candles emergence field | DESCRIBED — **OWED #74** | civilisations kindling one by one | P8 @ ~2:25–2:40 |',
  '| T152 Timeline bar with labelled era bands | DESCRIBED | 13.8 billion years as one proportion | P8 @ 3:00–3:35 |',
  '| T153 Duration-as-rows comparison bars | DESCRIBED — **OWED #75** | duration encoded as row count | P8 @ 4:00–4:15 |',
  '| T154 Window ellipse + players-joined chart | DESCRIBED — **OWED #76** | bunching drawn as a game lobby filling | P8 @ 4:30–4:51 |',
  '| T156 Isometric settlement diorama | DESCRIBED — **OWED #77** | expansion as a village filling its tile | P8 @ 5:30–5:55 |',
  '| T157 Detection-UI gag | DESCRIBED — **OWED #78** | loudness as an interface alert | P8 @ 6:20–6:35 |',
  '| T158 Forest-clearing analogy | DESCRIBED | the analogy staged at full weight | P8 @ 6:10–6:56 |',
  '| T159 Terraforming diorama | DESCRIBED | the deadline as an act on a world | P8 @ ~7:05–7:20 |',
  '| T160 Expansion-front envelopment | DESCRIBED — **OWED #79** | territory as an approaching blob | P8 @ 7:26–7:36 |',
  '| T161 Pedestal race staging | DESCRIBED | civilisations on starting blocks | P8 @ ~8:15–8:28 |',
  '| T162 Galaxy race table | DESCRIBED — **OWED #80** | the empty field, now crowded | P8 @ ~8:38–8:50 |',
  '| AS-62 Deadline as a distribution | asset | urgency without an invented date | P8 lessons (§6 L4) |',
  '| AS-63 Analogy at full production weight | asset | analogy beats get primary-scene budgets | P8 lessons (§6 L5) |',
  '| AS-64 Duration as row count | asset | extreme ratios as stacked rows | P8 lessons (§6 L6) |',
  '| AS-66 The envelopment diagram | asset | a border arriving, no villain required | P8 lessons (§6 L10) |'],
 '## Endings': [
  '| T164 Meet-as-equals council | DESCRIBED | the payoff staged as a greeting | P8 @ 9:30–9:52 |',
  '| T165 Merch outro as a designed end-card sequence | DESCRIBED | labelled, continuous, capped outro | P8 @ 9:57–10:57 |',
  '| AS-68 Labelled, capped commercial outro | asset | the ending prints its nature on its face | P8 lessons (§6 L12) |'],
 '## Cross-container systems & principles': [
  '| T148 Question-ladder sectioning | DESCRIBED | cumulative ladder across the whole essay (also in Openings) | P8 @ 1:00–8:29 |',
  '| T163 Envelopment personified | DESCRIBED | the worst case gets a face, late | P8 @ 9:10–9:25 |',
  '| AS-61 Cumulative chain, counted branch points | asset | dependency map as a Tab-0 artefact | P8 lessons (§6 L3) |',
  '| AS-67 Personify the stake once, late | asset | personification sequenced after the charts | P8 lessons (§6 L11) |',
  '| AS-69 Three-map essay segmentation | asset | semantic · visual · musical maps; cuts do not mark sections | P8 lessons (§6 L13) |'],
}
sections = list(NEW_ROWS.keys())
for idx, sec in enumerate(sections):
    start = v.find(sec)
    assert start >= 0, sec
    # end of this section = next '## ' heading or EOF
    nxt = v.find('\n## ', start + len(sec))
    seg = v[start:nxt if nxt >= 0 else len(v)]
    seg = seg.rstrip() + '\n' + '\n'.join(NEW_ROWS[sec]) + '\n'
    v = v[:start] + seg + (v[nxt:] if nxt >= 0 else '')
open(vp, 'w').write(v)
print('VIEWS updated', os.path.getsize(vp))
